    <div>
      <h2 data-ckey="wasIstHaarausfall.heading"<?= apex_cms_attrs_or($cmsHairpedia['wasIstHaarausfall']['heading'] ?? null, ['de' => "Was ist Haarausfall?", 'en' => "What is hair loss?"]) ?>><?= apex_cms_value_or($cmsHairpedia['wasIstHaarausfall']['heading'] ?? null, ['de' => "Was ist Haarausfall?", 'en' => "What is hair loss?"], $currentLang) ?></h2>
      <p data-ckey="wasIstHaarausfall.body"<?= apex_cms_attrs_or($cmsHairpedia['wasIstHaarausfall']['body'] ?? null, ['de' => "Haarausfall, medizinisch Alopezie genannt, ist das teilweise oder vollständige Fehlen von Haaren an Stellen, an denen sie normalerweise wachsen. Bis zu 100 Haare täglich zu verlieren gilt als normaler Teil des Wachstumszyklus.", 'en' => "Hair loss, medically known as alopecia, is the partial or complete absence of hair from areas where it normally grows. Losing up to 100 hairs a day is a normal part of the growth cycle."]) ?>><?= apex_cms_value_or($cmsHairpedia['wasIstHaarausfall']['body'] ?? null, ['de' => "Haarausfall, medizinisch Alopezie genannt, ist das teilweise oder vollständige Fehlen von Haaren an Stellen, an denen sie normalerweise wachsen. Bis zu 100 Haare täglich zu verlieren gilt als normaler Teil des Wachstumszyklus.", 'en' => "Hair loss, medically known as alopecia, is the partial or complete absence of hair from areas where it normally grows. Losing up to 100 hairs a day is a normal part of the growth cycle."], $currentLang) ?></p>
