      <p data-ckey="wasIstHaarausfall.t15"<?= apex_cms_attrs_or($cmsHairpedia['wasIstHaarausfall']['t15'] ?? null, ['de' => "Eine kurze Übergangsphase. Die Haarproduktion stoppt, der Follikel schrumpft und löst sich von der Blutversorgung.", 'en' => "A short transitional period. Hair production stops, the follicle shrinks, and detaches from its blood supply.", 'fr' => "Une brève période de transition. La production de cheveux s'arrête, le follicule rétrécit et se détache de son apport sanguin.", 'nl' => "Een korte overgangsperiode. De haarproductie stopt, de follikel krimpt en maakt zich los van de bloedtoevoer.", 'it' => "Un breve periodo di transizione. La produzione di capelli si arresta, il follicolo si restringe e si stacca dal proprio apporto sanguigno.", 'tr' => "Kısa bir geçiş dönemi. Saç üretimi durur, folikül küçülür ve kan akışından ayrılır."]) ?>><?= apex_cms_value_or($cmsHairpedia['wasIstHaarausfall']['t15'] ?? null, ['de' => "Eine kurze Übergangsphase. Die Haarproduktion stoppt, der Follikel schrumpft und löst sich von der Blutversorgung.", 'en' => "A short transitional period. Hair production stops, the follicle shrinks, and detaches from its blood supply.", 'fr' => "Une brève période de transition. La production de cheveux s'arrête, le follicule rétrécit et se détache de son apport sanguin.", 'nl' => "Een korte overgangsperiode. De haarproductie stopt, de follikel krimpt en maakt zich los van de bloedtoevoer.", 'it' => "Un breve periodo di transizione. La produzione di capelli si arresta, il follicolo si restringe e si stacca dal proprio apporto sanguigno.", 'tr' => "Kısa bir geçiş dönemi. Saç üretimi durur, folikül küçülür ve kan akışından ayrılır."], $currentLang) ?></p>
