    <div class="hp-card"><h4 data-ckey="arten.t6"<?= apex_cms_attrs_or($cmsHairpedia['arten']['t6'] ?? null, ['de' => "Alopecia areata", 'en' => "Alopecia areata", 'fr' => "Alopécie en plaques", 'nl' => "Alopecia areata", 'it' => "Alopecia areata", 'tr' => "Alopesi Areata"]) ?>><?= apex_cms_value_or($cmsHairpedia['arten']['t6'] ?? null, ['de' => "Alopecia areata", 'en' => "Alopecia areata", 'fr' => "Alopécie en plaques", 'nl' => "Alopecia areata", 'it' => "Alopecia areata", 'tr' => "Alopesi Areata"], $currentLang) ?></h4><p data-ckey="arten.t7"<?= apex_cms_attrs_or($cmsHairpedia['arten']['t7'] ?? null, ['de' => "Autoimmunerkrankung, bei der das Immunsystem Follikel angreift, meist runde Herde. In den meisten Fällen wächst das Haar zurück, kann aber unvorhersehbar verlaufen.", 'en' => "An autoimmune condition where the immune system attacks follicles, usually causing round patches. In most cases the hair regrows, though it can be unpredictable.", 'fr' => "Une maladie auto-immune dans laquelle le système immunitaire attaque les follicules, provoquant généralement des plaques rondes. Dans la plupart des cas, les cheveux repoussent, bien que cela puisse être imprévisible.", 'nl' => "Een auto-immuunaandoening waarbij het immuunsysteem follikels aanvalt, meestal met ronde plekken tot gevolg. In de meeste gevallen groeit het haar terug, al kan dit onvoorspelbaar verlopen.", 'it' => "Una condizione autoimmune in cui il sistema immunitario attacca i follicoli, causando solitamente chiazze rotonde. Nella maggior parte dei casi i capelli ricrescono, anche se in modo imprevedibile.", 'tr' => "Bağışıklık sisteminin foliküllere saldırdığı, genellikle yuvarlak lekelere neden olan otoimmün bir durumdur. Çoğu vakada saç yeniden çıkar, ancak seyri öngörülemez olabilir."]) ?>><?= apex_cms_value_or($cmsHairpedia['arten']['t7'] ?? null, ['de' => "Autoimmunerkrankung, bei der das Immunsystem Follikel angreift, meist runde Herde. In den meisten Fällen wächst das Haar zurück, kann aber unvorhersehbar verlaufen.", 'en' => "An autoimmune condition where the immune system attacks follicles, usually causing round patches. In most cases the hair regrows, though it can be unpredictable.", 'fr' => "Une maladie auto-immune dans laquelle le système immunitaire attaque les follicules, provoquant généralement des plaques rondes. Dans la plupart des cas, les cheveux repoussent, bien que cela puisse être imprévisible.", 'nl' => "Een auto-immuunaandoening waarbij het immuunsysteem follikels aanvalt, meestal met ronde plekken tot gevolg. In de meeste gevallen groeit het haar terug, al kan dit onvoorspelbaar verlopen.", 'it' => "Una condizione autoimmune in cui il sistema immunitario attacca i follicoli, causando solitamente chiazze rotonde. Nella maggior parte dei casi i capelli ricrescono, anche se in modo imprevedibile.", 'tr' => "Bağışıklık sisteminin foliküllere saldırdığı, genellikle yuvarlak lekelere neden olan otoimmün bir durumdur. Çoğu vakada saç yeniden çıkar, ancak seyri öngörülemez olabilir."], $currentLang) ?></p></div>
    <div class="hp-card"><h4 data-ckey="arten.t8"<?= apex_cms_attrs_or($cmsHairpedia['arten']['t8'] ?? null, ['de' => "Telogenes Effluvium", 'en' => "Telogen effluvium", 'fr' => "Effluvium télogène", 'nl' => "Telogeen effluvium", 'it' => "Effluvio telogen", 'tr' => "Telogen Effluvium"]) ?>><?= apex_cms_value_or($cmsHairpedia['arten']['t8'] ?? null, ['de' => "Telogenes Effluvium", 'en' => "Telogen effluvium", 'fr' => "Effluvium télogène", 'nl' => "Telogeen effluvium", 'it' => "Effluvio telogen", 'tr' => "Telogen Effluvium"], $currentLang) ?></h4><p data-ckey="arten.t9"<?= apex_cms_attrs_or($cmsHairpedia['arten']['t9'] ?? null, ['de' => "Vorübergehendes, diffuses Ausdünnen 2 bis 4 Monate nach Geburt, OP, schwerer Krankheit oder starkem Stress. Klingt meist innerhalb von 6 bis 12 Monaten ab.", 'en' => "Temporary diffuse shedding 2 to 4 months after childbirth, surgery, severe illness, or major stress. Usually resolves within 6 to 12 months.", 'fr' => "Chute diffuse temporaire, 2 à 4 mois après un accouchement, une opération, une maladie grave ou un stress important. Se résorbe généralement en 6 à 12 mois.", 'nl' => "Tijdelijke diffuse haaruitval, 2 tot 4 maanden na een bevalling, operatie, ernstige ziekte of grote stress. Verdwijnt meestal binnen 6 tot 12 maanden.", 'it' => "Perdita diffusa temporanea, 2-4 mesi dopo il parto, un intervento chirurgico, una malattia grave o uno stress importante. Si risolve solitamente entro 6-12 mesi.", 'tr' => "Doğum, ameliyat, ciddi hastalık veya yoğun stresten 2 ila 4 ay sonra görülen geçici, yaygın dökülmedir. Genellikle 6 ila 12 ay içinde geçer."]) ?>><?= apex_cms_value_or($cmsHairpedia['arten']['t9'] ?? null, ['de' => "Vorübergehendes, diffuses Ausdünnen 2 bis 4 Monate nach Geburt, OP, schwerer Krankheit oder starkem Stress. Klingt meist innerhalb von 6 bis 12 Monaten ab.", 'en' => "Temporary diffuse shedding 2 to 4 months after childbirth, surgery, severe illness, or major stress. Usually resolves within 6 to 12 months.", 'fr' => "Chute diffuse temporaire, 2 à 4 mois après un accouchement, une opération, une maladie grave ou un stress important. Se résorbe généralement en 6 à 12 mois.", 'nl' => "Tijdelijke diffuse haaruitval, 2 tot 4 maanden na een bevalling, operatie, ernstige ziekte of grote stress. Verdwijnt meestal binnen 6 tot 12 maanden.", 'it' => "Perdita diffusa temporanea, 2-4 mesi dopo il parto, un intervento chirurgico, una malattia grave o uno stress importante. Si risolve solitamente entro 6-12 mesi.", 'tr' => "Doğum, ameliyat, ciddi hastalık veya yoğun stresten 2 ila 4 ay sonra görülen geçici, yaygın dökülmedir. Genellikle 6 ila 12 ay içinde geçer."], $currentLang) ?></p></div>
    <div class="hp-card"><h4 data-ckey="arten.t10"<?= apex_cms_attrs_or($cmsHairpedia['arten']['t10'] ?? null, ['de' => "Traktionsalopezie", 'en' => "Traction alopecia", 'fr' => "Alopécie de traction", 'nl' => "Tractie-alopecia", 'it' => "Alopecia da trazione", 'tr' => "Traksiyon Alopesisi"]) ?>><?= apex_cms_value_or($cmsHairpedia['arten']['t10'] ?? null, ['de' => "Traktionsalopezie", 'en' => "Traction alopecia", 'fr' => "Alopécie de traction", 'nl' => "Tractie-alopecia", 'it' => "Alopecia da trazione", 'tr' => "Traksiyon Alopesisi"], $currentLang) ?></h4><p data-ckey="arten.t11"<?= apex_cms_attrs_or($cmsHairpedia['arten']['t11'] ?? null, ['de' => "Haarausfall durch dauerhaften Zug, etwa durch enge Zöpfe, Extensions oder Pferdeschwänze. Anfangs reversibel, kann bei anhaltendem Zug dauerhaft werden.", 'en' => "Hair loss from chronic tension, such as tight braids, extensions, or ponytails. Initially reversible, can become permanent if tension continues.", 'fr' => "Chute de cheveux due à une tension chronique, comme des tresses serrées, des extensions ou des queues de cheval. Réversible au début, peut devenir permanente si la tension persiste.", 'nl' => "Haaruitval door aanhoudende trekkracht, zoals strakke vlechten, extensions of paardenstaarten. Aanvankelijk omkeerbaar, kan permanent worden bij aanhoudende trek.", 'it' => "Perdita di capelli causata da tensione cronica, come trecce strette, extension o code di cavallo. Inizialmente reversibile, può diventare permanente se la tensione continua.", 'tr' => "Sıkı örgüler, kaynak saç veya at kuyruğu gibi sürekli çekme nedeniyle oluşan saç dökülmesidir. Başlangıçta geri dönüşlüdür, çekme devam ederse kalıcı hale gelebilir."]) ?>><?= apex_cms_value_or($cmsHairpedia['arten']['t11'] ?? null, ['de' => "Haarausfall durch dauerhaften Zug, etwa durch enge Zöpfe, Extensions oder Pferdeschwänze. Anfangs reversibel, kann bei anhaltendem Zug dauerhaft werden.", 'en' => "Hair loss from chronic tension, such as tight braids, extensions, or ponytails. Initially reversible, can become permanent if tension continues.", 'fr' => "Chute de cheveux due à une tension chronique, comme des tresses serrées, des extensions ou des queues de cheval. Réversible au début, peut devenir permanente si la tension persiste.", 'nl' => "Haaruitval door aanhoudende trekkracht, zoals strakke vlechten, extensions of paardenstaarten. Aanvankelijk omkeerbaar, kan permanent worden bij aanhoudende trek.", 'it' => "Perdita di capelli causata da tensione cronica, come trecce strette, extension o code di cavallo. Inizialmente reversibile, può diventare permanente se la tensione continua.", 'tr' => "Sıkı örgüler, kaynak saç veya at kuyruğu gibi sürekli çekme nedeniyle oluşan saç dökülmesidir. Başlangıçta geri dönüşlüdür, çekme devam ederse kalıcı hale gelebilir."], $currentLang) ?></p></div>
    <div class="hp-card"><h4 data-ckey="arten.t12"<?= apex_cms_attrs_or($cmsHairpedia['arten']['t12'] ?? null, ['de' => "Vernarbende Alopezie", 'en' => "Scarring alopecia", 'fr' => "Alopécie cicatricielle", 'nl' => "Littekenalopecia", 'it' => "Alopecia cicatriziale", 'tr' => "Skatrisyel Alopesi"]) ?>><?= apex_cms_value_or($cmsHairpedia['arten']['t12'] ?? null, ['de' => "Vernarbende Alopezie", 'en' => "Scarring alopecia", 'fr' => "Alopécie cicatricielle", 'nl' => "Littekenalopecia", 'it' => "Alopecia cicatriziale", 'tr' => "Skatrisyel Alopesi"], $currentLang) ?></h4><p data-ckey="arten.t13"<?= apex_cms_attrs_or($cmsHairpedia['arten']['t13'] ?? null, ['de' => "Follikel werden zerstört und durch Narbengewebe ersetzt, dauerhafter Haarverlust. Eine Transplantation ist bei aktiver Entzündung meist nicht geeignet.", 'en' => "Follicles are destroyed and replaced by scar tissue, causing permanent loss. Transplantation is generally unsuitable while inflammation is active.", 'fr' => "Les follicules sont détruits et remplacés par du tissu cicatriciel, entraînant une perte permanente. La greffe n'est généralement pas adaptée tant que l'inflammation est active.", 'nl' => "Follikels worden vernietigd en vervangen door littekenweefsel, wat leidt tot permanent haarverlies. Een transplantatie is doorgaans ongeschikt zolang de ontsteking actief is.", 'it' => "I follicoli vengono distrutti e sostituiti da tessuto cicatriziale, causando una perdita permanente. Il trapianto è generalmente sconsigliato finché l'infiammazione è attiva.", 'tr' => "Foliküller yok olur ve yerini skar dokusu alır, kalıcı saç kaybına yol açar. İltihap aktifken saç ekimi genellikle uygun değildir."]) ?>><?= apex_cms_value_or($cmsHairpedia['arten']['t13'] ?? null, ['de' => "Follikel werden zerstört und durch Narbengewebe ersetzt, dauerhafter Haarverlust. Eine Transplantation ist bei aktiver Entzündung meist nicht geeignet.", 'en' => "Follicles are destroyed and replaced by scar tissue, causing permanent loss. Transplantation is generally unsuitable while inflammation is active.", 'fr' => "Les follicules sont détruits et remplacés par du tissu cicatriciel, entraînant une perte permanente. La greffe n'est généralement pas adaptée tant que l'inflammation est active.", 'nl' => "Follikels worden vernietigd en vervangen door littekenweefsel, wat leidt tot permanent haarverlies. Een transplantatie is doorgaans ongeschikt zolang de ontsteking actief is.", 'it' => "I follicoli vengono distrutti e sostituiti da tessuto cicatriziale, causando una perdita permanente. Il trapianto è generalmente sconsigliato finché l'infiammazione è attiva.", 'tr' => "Foliküller yok olur ve yerini skar dokusu alır, kalıcı saç kaybına yol açar. İltihap aktifken saç ekimi genellikle uygun değildir."], $currentLang) ?></p></div>
